def count_arrangements(N, K):
    # Initialize DP table
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(K + 1):
            # Case 1: Add a red ball
            dp[i][j] = dp[i-1][j]

            # Case 2: Add a blue ball
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i-1][j-1]) % MOD

            # Case 3: Extend a previous blue sequence
            if j > 0 and i > j:
                dp[i][j] = (dp[i][j] + j * dp[i-1][j]) % MOD

    # Sum up the results for each number of moves
    result = [0] * K
    for i in range(1, K + 1):
        result[i-1] = dp[N][i]

    return result

