def count_arrangements(N, K):
    MOD = 10**9 + 7

    # dp[i][j] means the number of ways to arrange j blue balls such that
    # Takahashi needs exactly i moves to collect all the blue balls.
    dp = [[0] * (K + 1) for _ in range(K + 1)]
    dp[0][0] = 1  # There is one way to arrange 0 blue balls and need 0 moves

    # Iterate over the number of moves needed
    for i in range(1, K + 1):
        # Iterate over the number of blue balls taken
        for j in range(K + 1):
            # Try to place a sequence of i blue balls into the j blue balls slots
            for k in range(N - j + 1):
                if j >= i:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - i]) % MOD

    # The result for each i is the number of ways to arrange j blue balls
    # where j = i to i (we need exactly i moves to collect all i blue balls)
    result = []
    for i in range(1, K + 1):
        result.append(dp[i][i])

    return result

